rows.attributes:
key={d}
              href={withParam({ density: d === 'comfortable' ? undefined : d })}
              scroll={false}
              aria-current={density === d ? 'true' : undefined}
              className={buttonVariants({
                variant: density === d ? 'outline' : 'ghost',
                size: 'sm',
              })}

type="button"
            onClick={retry}
            className="rounded-md border border-input px-4 py-2 text-sm font-medium hover:bg-accent"

type={type}
      data-slot="button"
      className={cn(buttonVariants({ variant, size }), className)}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      {...props}

href={hrefForPage(item)}
                aria-label={`Page ${item}`}
                aria-current={item === page ? 'page' : undefined}
                className={buttonVariants({
                  variant: item === page ? 'secondary' : 'ghost',
                  size: 'sm',
                })}

variant="outline"
              size="sm"
              onClick={() => {
                setSettled(null)
                setRetry((n) => n + 1)
              }}

type="button"
      data-slot="task-choice"
      aria-pressed={pressed}
      onClick={onClick}
      className={cn(
        'control-target flex items-start gap-3 rounded-md border p-3 text-left text-sm hover:bg-muted/50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring',
        pressed && 'border-primary bg-accent',
      )}

variant="ghost"
        onClick={() => setOpen(true)}
        aria-label={locale === 'vi' ? 'Tìm trang' : 'Search pages'}
        className={cn('app-search-trigger text-muted-foreground', className)}

size="icon"
            variant="ghost"
            className="size-7"
            aria-label={`Edit ${label}`}
            onClick={() => {
              setDraft(value)
              setResult(null)
              setEditing(true)
            }}

type="button"
          size="sm"
          variant="ghost"
          disabled={pending}
          onClick={() => setEditing(false)}

type="button"
                className="inline-flex items-center gap-1 underline"
                onClick={() => router.refresh()}

label="Reopen"
        confirmLabel="Reopen record"
        warning={`Reopen “${record.title}”? It returns to the open lists.`}
        variant="primary"
        run={() =>
          updateContextAction({
            matterId,
            recordId: record.id,
            ifMatch: record.etag,
            action: 'reopen',
            reason: '',
          })
        }

variant="secondary"
            className="md:col-span-2 md:w-fit"
            onClick={() => {
              invalidate()
              setRows((rs) => rs.filter((_, j) => j !== i))
            }}

variant="secondary"
          disabled={pending || locked}
          onClick={() => {
            invalidate()
            setRows((rs) => [
              ...rs,
              {
                rowKey: `row-${next.current++}`,
                itemId: '',
                expectedRevision: '1',
                title: unchanged(),
                description: unchanged(),
                internalOwner: unchanged(),
                due: unchanged(),
              },
            ])
          }}

variant="secondary"
          disabled={pending || rows.length === 0 || locked}
          onClick={() =>
            start(async () => {
              setPreviewError(null)
              const r = await bulkPreviewAction(matterId, inputs)
              if (r.ok && r.preview) {
                setPreview({ result: r.preview, fingerprint, inputs })
                setOutcome(null)
              } else if (!r.ok && ACCESS_LOST.has(r.kind)) {
                purge()
              } else if (!r.ok) {
                setPreview(null)
                setPreviewError(r.error)
              }
            })
          }

variant="secondary"
          disabled={pending || !file || locked}
          onClick={() =>
            start(async () => {
              if (!file) return
              setPreviewError(null)
              const r = await importPreviewAction(matterId, file)
              if (r.ok && r.preview) {
                setPreview({
                  result: r.preview,
                  fingerprint: importFingerprint(
                    file,
                    r.preview.rows.map((x) => x.rowKey),
                  ),
                })
                setOutcome(null)
                setIntent(null)
              } else if (!r.ok && ACCESS_LOST.has(r.kind)) {
                purge()
              } else if (!r.ok) {
                setPreview(null)
                setPreviewError(r.error)
              }
            })
          }

variant="secondary"
          disabled={pending || retained?.some((attempt) => attempt.blocked)}
          onClick={() => void retry()}

name="requirementId"
            legend={
              <LocalizedText
                en="Requirement this filing serves"
                vi="Yêu cầu mà thủ tục này phục vụ"
              />
            }
            searchLabel={
              <LocalizedText
                en="Search this matter’s Requirements by title"
                vi="Tìm yêu cầu của hồ sơ theo tiêu đề"
              />
            }
            required
            search={(query) => searchRecords({ matterId, query, kind: 'REQUIREMENT' })}
            hint={
              <LocalizedText
                en="Approval never completes or verifies the Requirement by itself."
                vi="Phê duyệt thủ tục không tự động hoàn tất hoặc xác minh yêu cầu."
              />
            }
            error={errors.requirementId?.[0]}

name="userId"
                  active={open}
                  legend={<LocalizedText en="Workspace member" vi="Thành viên không gian" />}
                  searchLabel={
                    <LocalizedText
                      en="Search workspace members by name"
                      vi="Tìm thành viên không gian theo tên"
                    />
                  }
                  required
                  eligible={eligible}
                  search={async (query) => {
                    const q = query.toLowerCase()
                    return {
                      status: 'ok',
                      options: eligible.filter((o) => o.label.toLowerCase().includes(q)),
                    }
                  }}
                  noMatch={
                    <LocalizedText
                      en="No one to add. Everyone matching is already on this matter; add people to the workspace first to include them here."
                      vi="Không còn ai để thêm. Mọi người khớp đã có trong hồ sơ; hãy thêm họ vào không gian làm việc trước."
                    />
                  }
                  hint={
                    <LocalizedText
                      en="Only active members of this workspace can be added."
                      vi="Chỉ thêm được thành viên đang hoạt động trong không gian làm việc."
                    />
                  }
                  error={errors.userId?.[0]}

variant="ghost"
        size="icon"
        aria-label={`Delete ${task.title}`}
        onClick={() => {
          setError(undefined)
          setOpen(true)
        }}

aria-label="Search tasks"
        placeholder="Search tasks…"
        className="sm:w-72"
        maxLength={TASK_SEARCH_MAX_LENGTH}
        value={query}
        onChange={(event) => {
          const next = event.target.value
          setQuery(next)
          clearTimeout(timer.current)
          timer.current = setTimeout(() => navigate(next, statusValue), SEARCH_DEBOUNCE_MS)
        }}
        onClear={() => {
          setQuery('')
          navigate('', statusValue)
        }}

caption="Tasks"
      columns={columns}
      rows={tasks}
      getRowKey={(task) => task.id}
      empty={
        <EmptyState
          icon={<ListTodo />}
          title={filtered ? 'No matching tasks' : 'No tasks yet'}
          description={
            filtered
              ? 'Try a different search term or status filter.'
              : 'Create your first task to get started.'
          }
        />
      }

name="sourceId"
                legend={<LocalizedText en="Must be satisfied first" vi="Phải được đáp ứng trước" />}
                searchLabel={
                  <LocalizedText
                    en="Search this matter’s records by title"
                    vi="Tìm bản ghi của hồ sơ theo tiêu đề"
                  />
                }
                required
                search={(query) => searchWorkItemsAction({ matterId, query, excludeId: it.id })}
                noMatch={
                  <LocalizedText
                    en="No record you can read matches. Check the title, or add the record first."
                    vi="Không có bản ghi nào bạn xem được khớp. Kiểm tra tiêu đề hoặc thêm bản ghi trước."
                  />
                }
                hint={
                  <LocalizedText
                    en="Every record you can read is searchable, not only the first page."
                    vi="Tìm được mọi bản ghi bạn xem được, không chỉ trang đầu."
                  />
                }
                error={errors.sourceId?.[0]}

href={without(['q', ...filters.map((f) => f.name)])}
            scroll={false}
            className={buttonVariants({ variant: 'ghost', size: 'sm' })}

name="userId"
                  active={open}
                  legend={<LocalizedText en="Person" vi="Thành viên" />}
                  searchLabel={<LocalizedText en="Search people by name" vi="Tìm người theo tên" />}
                  required
                  search={(query) => searchWorkspacePeopleAction({ workspaceId, query })}
                  noMatch={
                    <LocalizedText
                      en="No matching people to add. Try another name, or provision their product account first."
                      vi="Không tìm thấy người để thêm. Thử tên khác hoặc tạo tài khoản sản phẩm cho họ trước."
                    />
                  }
                  hint={
                    <LocalizedText
                      en="Type a name to search. The person must already have a product account."
                      vi="Nhập tên để tìm. Người này phải có sẵn tài khoản sản phẩm."
                    />
                  }
                  error={errors.userId?.[0]}

label="Remove"
      confirmLabel="Remove member"
      warning={
        self
          ? 'Remove yourself from this workspace? You will lose access to it immediately.'
          : 'Remove this member from the workspace? Their access to all its matters ends immediately.'
      }
      run={() => revokeWorkspaceMemberAction({ workspaceId, userId, ifMatch })}
